out = {"section": "Literacy extras: comprehension ladder, reading tests, novel task maps, writing frames and spot the difference", "lessons": lessons}
with open(os.path.join(ROOT, "content", "lessons", "24-literacy-extras.json"), "w", encoding="utf-8") as f:
    json.dump(out, f, ensure_ascii=False, indent=1)
print(len(lessons), "lessons")
